import parseMidi from "@audio/midi-parse";
import writeMidi from "@audio/midi-write";
import type { Note } from "../playback/note";

const SECONDS_PER_MINUTE = 60;
const MICROSECONDS_PER_MINUTE = 60_000_000;

/** What a file input or a drop zone accepts as a MIDI file. */
export const MIDI_FILE_ACCEPT = ".mid,.midi,audio/midi,audio/x-midi";

/** The grid notes are read onto: steps a quarter note, the clip's length in steps, and the pitch and tempo ranges it takes. */
export interface MidiFileGrid {
  /** The clip's length, in steps: notes starting past it are dropped. */
  duration: number;
  /** @default 200 */
  maxBpm?: number;
  /** @default 127 */
  maxPitch?: number;
  /** @default 20 */
  minBpm?: number;
  /** @default 0 */
  minPitch?: number;
  /** Steps in a quarter note: 4 makes a step a sixteenth. @default 4 */
  stepsPerQuarter?: number;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

/**
 * Reads a MIDI file's notes onto a grid of steps, with the file's own tempo
 * (clamped to the BPM range). Each note is quantized to the nearest step and
 * at least one step long; notes starting past the clip's end are dropped.
 */
export async function readMidiFile(
  file: Blob,
  grid: MidiFileGrid
): Promise<{ bpm: number; notes: Note[] }> {
  const {
    duration,
    maxBpm = 200,
    maxPitch = 127,
    minBpm = 20,
    minPitch = 0,
    stepsPerQuarter = 4,
  } = grid;
  const { bpm: fileBpm, parts } = await readMidiFileParts(file);
  const bpm = clamp(Math.round(fileBpm), minBpm, maxBpm);
  const notes: Note[] = [];
  for (const midiNote of parts.flatMap((part) => part.notes)) {
    const start = Math.round(midiNote.start * stepsPerQuarter);
    if (start < 0 || start >= duration) {
      continue;
    }
    notes.push({
      id: `midi-import-${notes.length}`,
      length: clamp(
        Math.round(midiNote.length * stepsPerQuarter),
        1,
        duration - start
      ),
      pitch: clamp(midiNote.pitch, minPitch, maxPitch),
      start,
      velocity: clamp(midiNote.velocity, 0, 1),
    });
  }
  return { bpm, notes };
}

/** A note of a score in beats: where it starts and how long it lasts, in quarter notes. */
export interface ScoreNote {
  length: number;
  pitch: number;
  start: number;
  /** 0 to 1. */
  velocity: number;
}

/** One part of a score: its name, whether it is drums, and its notes in beats. */
export interface ScorePart {
  /** On MIDI channel 10, the drums of General MIDI. */
  drums: boolean;
  name: string;
  notes: ScoreNote[];
  /** The General MIDI program it asks for, 0 to 127, when it names one: 0 is a piano, 32 a bass. */
  program?: number;
}

/** MIDI's channel 10, counted from 0: the drums. */
const DRUM_CHANNEL = 9;
const MICROSECONDS_PER_SECOND = 1_000_000;
const META_TRACK_NAME = 3;

/**
 * Reads a MIDI file as parts, for a host that lays each on a track of its
 * own: a part per track and channel, named after its track (and its channel,
 * when a track holds several), its notes in beats as they were written, not
 * quantized and not cut, at least a tick long, and the first program its
 * channel plays. Also the file's first tempo, unrounded. The file is parsed
 * by `@audio/midi-parse`.
 */
export async function readMidiFileParts(
  file: Blob
): Promise<{ bpm: number; parts: ScorePart[] }> {
  const parsed = parseMidi(new Uint8Array(await file.arrayBuffer()));
  // The parser times notes in seconds: its tempo map turns them back into beats.
  const beatOf = (seconds: number) => {
    let [mark] = parsed.tempos;
    for (const tempo of parsed.tempos) {
      if (tempo.time > seconds) {
        break;
      }
      mark = tempo;
    }
    if (!mark) {
      return 0;
    }
    return (
      mark.tick / parsed.division +
      ((seconds - mark.time) * MICROSECONDS_PER_SECOND) / mark.usPerBeat
    );
  };
  const byPart = new Map<number, ScoreNote[]>();
  for (const midiNote of parsed.notes) {
    const key = midiNote.track * 16 + midiNote.channel;
    const notes = byPart.get(key) ?? [];
    const start = beatOf(midiNote.time);
    notes.push({
      length: Math.max(
        1 / parsed.division,
        beatOf(midiNote.time + midiNote.duration) - start
      ),
      pitch: midiNote.midi,
      start,
      velocity: midiNote.velocity,
    });
    byPart.set(key, notes);
  }
  const keys = [...byPart.keys()].sort((a, b) => a - b);
  const channelsOf = (track: number) =>
    keys.filter((key) => Math.floor(key / 16) === track).length;
  const events = parsed.tracks.map((track, index) => ({ index, track }));
  const programOf = (track: number, channel: number) => {
    // On its own track first; a format 0 file, or a tempo track, may set it elsewhere.
    for (const onItsOwn of [true, false]) {
      for (const { index, track: list } of events) {
        if (onItsOwn && index !== track) {
          continue;
        }
        const event = list.find(
          (each) => each.type === "program" && each.channel === channel
        );
        if (typeof event?.program === "number") {
          return event.program;
        }
      }
    }
  };
  const nameOf = (track: number) => {
    const event = parsed.tracks[track]?.find(
      (each) => each.type === "meta" && each.meta === META_TRACK_NAME
    );
    return typeof event?.text === "string" ? event.text.trim() : "";
  };
  const [first] = parsed.tempos;
  return {
    bpm: first ? MICROSECONDS_PER_MINUTE / first.usPerBeat : 120,
    parts: keys.map((key) => {
      const track = Math.floor(key / 16);
      const channel = key % 16;
      const named = nameOf(track) || `Track ${track + 1}`;
      const program = programOf(track, channel);
      return {
        drums: channel === DRUM_CHANNEL,
        name:
          channelsOf(track) > 1 ? `${named}, channel ${channel + 1}` : named,
        notes: byPart.get(key) ?? [],
        ...(program === undefined ? {} : { program }),
      };
    }),
  };
}

/** The notes as a Standard MIDI File, the inverse of `readMidiFile`. Deactivated notes are left out. */
export function writeMidiFile(
  notes: readonly Note[],
  { bpm, stepsPerQuarter = 4 }: { bpm: number; stepsPerQuarter?: number }
): Uint8Array {
  // The writer takes seconds: a step lasts a quarter note over `stepsPerQuarter`.
  const secondsPerStep = SECONDS_PER_MINUTE / bpm / stepsPerQuarter;
  return writeMidi(
    notes
      .filter((note) => !note.muted)
      .map((note) => ({
        channel: 0,
        duration: note.length * secondsPerStep,
        midi: note.pitch,
        time: note.start * secondsPerStep,
        velocity: note.velocity ?? 1,
      })),
    { bpm }
  );
}

/** Saves the notes as a `.mid` file, named `filename`. */
export function downloadMidiFile(
  notes: readonly Note[],
  options: { bpm: number; filename?: string; stepsPerQuarter?: number }
) {
  const bytes = writeMidiFile(notes, options);
  // `Uint8Array`'s `.buffer` types as `ArrayBufferLike` (which also covers
  // `SharedArrayBuffer`) while `BlobPart` wants a concrete `ArrayBuffer`,
  // safe here since the writer always builds a fresh, non-shared one.
  const blob = new Blob([bytes.buffer as ArrayBuffer], { type: "audio/midi" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = options.filename ?? "clip.mid";
  link.click();
  URL.revokeObjectURL(url);
}

import writeMusicXml, { parse, type TempoPoint } from "@audio/musicxml";
import { strFromU8, unzipSync } from "fflate";
import type { Note } from "../playback/note";
import type { ScoreNote, ScorePart } from "./midi-file";

const SECONDS_PER_MINUTE = 60;
/** The tempo a part with no tempo marks is read at, as the parser reads it. */
const DEFAULT_BPM = 120;
/** A compressed score names its score in this file. */
const CONTAINER = "META-INF/container.xml";
const ROOT_FILE = /<rootfile[^>]*full-path="([^"]+)"/;
/** The grids the writer quantizes to, as the note value of a step. */
const GRIDS = [4, 8, 16, 32];

/** What a file input or a drop zone accepts as a MusicXML file: a score, or one compressed as `.mxl`. */
export const MUSICXML_FILE_ACCEPT =
  ".musicxml,.mxl,.xml,application/vnd.recordare.musicxml+xml,application/vnd.recordare.musicxml";

/** The grid notes are read onto: steps a quarter note, the clip's length in steps, and the pitch and tempo ranges it takes. */
export interface MusicXmlFileGrid {
  /** The clip's length, in steps: notes starting past it are dropped. */
  duration: number;
  /** @default 200 */
  maxBpm?: number;
  /** @default 127 */
  maxPitch?: number;
  /** @default 20 */
  minBpm?: number;
  /** @default 0 */
  minPitch?: number;
  /** Steps in a quarter note: 4 makes a step a sixteenth. @default 4 */
  stepsPerQuarter?: number;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

/**
 * The beat a time in seconds falls on, through a part's tempo marks: the
 * parser times each part by its own, so turning them back gives every part
 * the beats it was written in.
 */
function beatOf(seconds: number, tempos: readonly TempoPoint[]) {
  const marks = tempos.length > 0 ? tempos : [{ bpm: DEFAULT_BPM, time: 0 }];
  let beat = 0;
  for (const [index, mark] of marks.entries()) {
    const next = marks[index + 1];
    if (!next || seconds < next.time) {
      return beat + ((seconds - mark.time) * mark.bpm) / SECONDS_PER_MINUTE;
    }
    beat += ((next.time - mark.time) * mark.bpm) / SECONDS_PER_MINUTE;
  }
  return beat;
}

/** A score's text: as it is, or out of the `.mxl` archive that holds it, in UTF-8 or UTF-16 by its byte-order mark. */
async function scoreText(file: Blob) {
  let bytes: Uint8Array = new Uint8Array(await file.arrayBuffer());
  // A zip begins "PK": a compressed score, its container naming the score inside.
  if (bytes[0] === 0x50 && bytes[1] === 0x4b) {
    // An archive may hold any files, or none of these: a path can be missing.
    const files: Partial<Record<string, Uint8Array>> = unzipSync(bytes);
    const container = files[CONTAINER];
    const root = container ? ROOT_FILE.exec(strFromU8(container))?.[1] : null;
    const score = root ? files[root] : undefined;
    if (!score) {
      throw new Error("A compressed MusicXML file names no score it holds");
    }
    bytes = score;
  }
  if (bytes[0] === 0xff && bytes[1] === 0xfe) {
    return new TextDecoder("utf-16le").decode(bytes);
  }
  if (bytes[0] === 0xfe && bytes[1] === 0xff) {
    return new TextDecoder("utf-16be").decode(bytes);
  }
  return new TextDecoder().decode(bytes);
}

/**
 * Reads a MusicXML score as parts, for a host that lays each on a track of
 * its own: a part each, by its name, its notes in beats as they were
 * written, through changes of tempo, not quantized and not cut. A score, or
 * one compressed as `.mxl`. Grace notes, which take no time, are dropped, and
 * repeats play once, as written. Also its first tempo and its title.
 */
export async function readMusicXmlFileParts(
  file: Blob
): Promise<{ bpm: number; parts: ScorePart[]; title?: string }> {
  const score = parse(await scoreText(file));
  const parts = score.parts.map((part, index) => {
    const notes: ScoreNote[] = [];
    for (const scoreNote of part.notes) {
      if (scoreNote.duration > 0) {
        const start = beatOf(scoreNote.time, part.tempos);
        notes.push({
          length:
            beatOf(scoreNote.time + scoreNote.duration, part.tempos) - start,
          pitch: scoreNote.midi,
          start,
          velocity: scoreNote.velocity,
        });
      }
    }
    return { drums: false, name: part.name || `Part ${index + 1}`, notes };
  });
  return {
    bpm: score.parts[0]?.tempos[0]?.bpm ?? DEFAULT_BPM,
    parts,
    title: score.title,
  };
}

/**
 * Reads a MusicXML score's notes onto a grid of steps, with its first tempo
 * (clamped to the BPM range), every part into the one clip. A score, or one
 * compressed as `.mxl`. Each note is quantized to the nearest step and at
 * least one step long; notes starting past the clip's end are dropped, and so
 * are grace notes, which take no time. Repeats play once, as written.
 */
export async function readMusicXmlFile(
  file: Blob,
  grid: MusicXmlFileGrid
): Promise<{ bpm: number; notes: Note[]; title?: string }> {
  const {
    duration,
    maxBpm = 200,
    maxPitch = 127,
    minBpm = 20,
    minPitch = 0,
    stepsPerQuarter = 4,
  } = grid;
  const score = await readMusicXmlFileParts(file);
  const notes: Note[] = [];
  for (const part of score.parts) {
    for (const scoreNote of part.notes) {
      const start = Math.round(scoreNote.start * stepsPerQuarter);
      if (start < 0 || start >= duration) {
        continue;
      }
      notes.push({
        id: `musicxml-import-${notes.length}`,
        length: clamp(
          Math.round((scoreNote.start + scoreNote.length) * stepsPerQuarter) -
            start,
          1,
          duration - start
        ),
        pitch: clamp(scoreNote.pitch, minPitch, maxPitch),
        start,
        velocity: clamp(scoreNote.velocity, 0, 1),
      });
    }
  }
  return {
    bpm: clamp(Math.round(score.bpm), minBpm, maxBpm),
    notes,
    title: score.title,
  };
}

/**
 * The notes as a MusicXML score, the inverse of `readMusicXmlFile`, for a
 * notation app to open: on the grid they sit on, so nothing moves. Deactivated
 * notes are left out.
 */
export function writeMusicXmlFile(
  notes: readonly Note[],
  {
    bpm,
    stepsPerQuarter = 4,
    title,
  }: { bpm: number; stepsPerQuarter?: number; title?: string }
): string {
  const secondsPerStep = SECONDS_PER_MINUTE / bpm / stepsPerQuarter;
  return writeMusicXml(
    notes
      .filter((note) => !note.muted)
      .map((note) => ({
        duration: note.length * secondsPerStep,
        midi: note.pitch,
        time: note.start * secondsPerStep,
        velocity: note.velocity ?? 1,
      })),
    {
      bpm,
      // A step is a sixteenth at 4 a quarter, a thirty-second at 8; on a grid
      // the writer has no name for, it writes the lengths as they are.
      quantize: GRIDS.includes(stepsPerQuarter * 4) ? stepsPerQuarter * 4 : 0,
      title,
      triplets: false,
    }
  );
}

/** Saves the notes as a `.musicxml` file, named `filename`. */
export function downloadMusicXmlFile(
  notes: readonly Note[],
  options: {
    bpm: number;
    filename?: string;
    stepsPerQuarter?: number;
    title?: string;
  }
) {
  const blob = new Blob([writeMusicXmlFile(notes, options)], {
    type: "application/vnd.recordare.musicxml+xml",
  });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = options.filename ?? "clip.musicxml";
  link.click();
  URL.revokeObjectURL(url);
}

import {
  highpass,
  lowpass,
  notch,
  process as processSection,
} from "@audio/biquad";
import noiseShaping from "@audio/effect-noiseshaper";
import { loudnessGain, measureLoudness } from "../analysis/loudness";

const dbToGain = (db: number) => 10 ** (db / 20);

/** Every channel, `db` louder or quieter. */
export function gainChannels(
  channels: readonly Float32Array[],
  db: number
): Float32Array[] {
  const gain = dbToGain(db);
  return channels.map((channel) => channel.map((sample) => sample * gain));
}

/** What a sound is normalized to: its loudest sample, or its integrated loudness held under a true-peak ceiling. */
export type NormalizeTarget =
  | { peak: number }
  | { ceiling?: number; lufs: number };

/**
 * The sound, with one gain on every channel, so the balance between them
 * stays: to a peak in dBFS, or to a loudness in LUFS as far as its true peak
 * stays under `ceiling` (-1 dBTP by default). Silence comes back as it is.
 */
export function normalizeChannels(
  channels: readonly Float32Array[],
  sampleRate: number,
  target: NormalizeTarget
): Float32Array[] {
  const loudness = measureLoudness(channels, sampleRate);
  const db =
    "peak" in target
      ? target.peak - loudness.peak
      : loudnessGain(loudness, target.lufs, target.ceiling);
  return Number.isFinite(db) ? gainChannels(channels, db) : [...channels];
}

/**
 * A sound's balance: -1 is all left, 1 all right, 0 as it is. The side that
 * is turned away is attenuated and the other is left alone, so the centre
 * loses nothing. A mono sound becomes stereo to be placed; any other channel
 * count comes back as it is.
 */
export function panChannels(
  channels: readonly Float32Array[],
  pan: number
): Float32Array[] {
  const [first] = channels;
  const [left, right] =
    channels.length === 1 && first ? [first, first] : channels;
  if (!((channels.length === 1 || channels.length === 2) && left && right)) {
    return [...channels];
  }
  const at = Math.max(-1, Math.min(1, pan));
  const toLeft = at > 0 ? 1 - at : 1;
  const toRight = at < 0 ? 1 + at : 1;
  return [
    left.map((sample) => sample * toLeft),
    right.map((sample) => sample * toRight),
  ];
}

/** A filter's shape: what it lets through, 12 dB an octave. */
export type FilterType = "highpass" | "lowpass" | "notch";

/** Each filter's design, as a map: a type it does not hold finds nothing, not a function every object inherits. */
const DESIGNS = new Map<string, typeof lowpass>(
  Object.entries({ highpass, lowpass, notch } satisfies Record<
    FilterType,
    typeof lowpass
  >)
);

/**
 * Every channel through one filter of the cookbook, at `frequency` in hertz
 * and a `q` (one over the square root of two by default, the flattest). A
 * frequency at or over the Nyquist limit comes back as it is, and a type
 * other than `highpass`, `lowpass` or `notch` throws a `RangeError`.
 */
export function filterChannels(
  channels: readonly Float32Array[],
  sampleRate: number,
  { frequency, q, type }: { frequency: number; q?: number; type: FilterType }
): Float32Array[] {
  if (!(frequency > 0 && frequency < sampleRate / 2)) {
    return [...channels];
  }
  const design = DESIGNS.get(type);
  if (typeof design !== "function") {
    throw new RangeError(`There is no filter type called "${type}".`);
  }
  const coefficients = design(frequency, q, sampleRate);
  return channels.map((channel) => {
    const out = Float32Array.from(channel);
    processSection(out, coefficients);
    return out;
  });
}

/**
 * How a sound is brought to fewer bits: `tpdf` adds triangular noise one
 * step wide before rounding, so the error is steady noise instead of
 * distortion that follows the sound; `shaped` does the same with the error
 * fed back through two delays, which moves the noise up toward the highest
 * frequencies, where the ear hears it least; `feedback` rounds with the
 * error fed back once (`@audio/effect-noiseshaper`), with no added noise.
 */
export const DITHER_METHODS = ["tpdf", "shaped", "feedback"] as const;

export type DitherMethod = (typeof DITHER_METHODS)[number];

const triangular = () => Math.random() - Math.random();

/**
 * Every channel rounded to `bits` bits, by one of `DITHER_METHODS`, the way
 * a sound is mastered to 16 bits or 8: as many steps as that depth has, and
 * the error made into noise by the method. A source is not changed.
 */
export function ditherChannels(
  channels: readonly Float32Array[],
  bits: number,
  method: DitherMethod = "tpdf"
): Float32Array[] {
  const depth = Math.max(1, Math.min(24, Math.round(bits)));
  const levels = 2 ** (depth - 1) - 1;
  const step = 1 / levels;
  return channels.map((channel) => {
    const out = new Float32Array(channel.length);
    if (method === "feedback") {
      out.set(channel);
      return noiseShaping(out, { bits: depth }) as Float32Array;
    }
    // NTF = (1 - z^-1)^2: the error of the two samples before is taken off the next.
    let e1 = 0;
    let e2 = 0;
    for (let index = 0; index < channel.length; index += 1) {
      const wanted =
        (channel[index] as number) - (method === "shaped" ? 2 * e1 - e2 : 0);
      const made = Math.round((wanted + triangular() * step) * levels) * step;
      out[index] = made;
      e2 = e1;
      e1 = made - wanted;
    }
    return out;
  });
}

import { pitchShift } from "@audio/shift";
import {
  hybrid,
  paulstretch,
  pvocLock,
  pvsola,
  transient,
  wsola,
} from "@audio/stretch";
import { resampleChannels } from "./channels";

/**
 * The ways a sound is stretched in time with its pitch kept, each with what
 * it suits: a phase vocoder that keeps the attacks of drums (`transient`),
 * one for general music (`pvocLock`), waveform overlap-add for speech made
 * shorter (`wsola`) or longer (`pvsola`), a vocoder with the harmonic and
 * percussive parts apart for full mixes (`hybrid`), and the extreme
 * stretch of ambient textures (`paulstretch`).
 */
export const STRETCH_METHODS = [
  "transient",
  "pvocLock",
  "wsola",
  "pvsola",
  "hybrid",
  "paulstretch",
] as const;

export type StretchMethod = (typeof STRETCH_METHODS)[number];

type Options = { factor: number; sampleRate: number };
type Together = (data: Float32Array[], options: Options) => Float32Array[];
type Apart = (data: Float32Array, options: Options) => Float32Array;

/** `wsola` takes every channel at once and shares one search, so the channels stay in phase. */
const together: Together = (data, options) => wsola(data, options);

/** The others take one channel at a time: a map, so a name it does not hold finds nothing, not a function every object inherits. */
const APART = new Map<string, Apart>(
  Object.entries({
    hybrid: (data, options) => hybrid(data, options),
    paulstretch: (data, options) => paulstretch(data, options),
    pvocLock: (data, options) => pvocLock(data, options),
    pvsola: (data, options) => pvsola(data, options),
    transient: (data, options) => transient(data, options),
  } satisfies Record<Exclude<StretchMethod, "wsola">, Apart>)
);

/**
 * Every channel `factor` times as long, its pitch unchanged: 2 is twice as
 * slow, 0.5 twice as fast. The channels share one analysis where the method
 * allows it (`wsola`), so they stay in phase; the other methods take them
 * one by one. A method not in `STRETCH_METHODS` throws a `RangeError`.
 */
export function stretchChannels(
  channels: readonly Float32Array[],
  sampleRate: number,
  { factor, method = "transient" }: { factor: number; method?: StretchMethod }
): Float32Array[] {
  if (!(factor > 0) || factor === 1 || channels.length === 0) {
    return [...channels];
  }
  const options: Options = { factor, sampleRate };
  if (method === "wsola") {
    return together([...channels], options);
  }
  const apart = APART.get(method);
  if (typeof apart !== "function") {
    throw new RangeError(`There is no stretch method called "${method}".`);
  }
  // Called here, where the check above holds, not in a callback.
  const stretched: Float32Array[] = [];
  for (const channel of channels) {
    stretched.push(apart(channel, options));
  }
  return stretched;
}

/** How a pitch is shifted: let the library choose from the sound (`auto`), or a method by name. */
export const SHIFT_METHODS = [
  "auto",
  "transient",
  "phaseLock",
  "formant",
  "wsola",
  "psola",
] as const;

export type ShiftMethod = (typeof SHIFT_METHODS)[number];

/**
 * Every channel `semitones` higher or lower, its length unchanged. `formant`
 * keeps a voice's character, where the others move it with the pitch.
 */
export function shiftChannels(
  channels: readonly Float32Array[],
  sampleRate: number,
  { method = "auto", semitones }: { method?: ShiftMethod; semitones: number }
): Float32Array[] {
  if (semitones === 0 || channels.length === 0) {
    return [...channels];
  }
  return pitchShift([...channels], {
    method: method === "auto" ? undefined : method,
    sampleRate,
    semitones,
  });
}

/**
 * The sound played `speed` times as fast, its pitch moving with it as on a
 * tape or a record: 2 is twice as fast and an octave up. The sample rate
 * stays, the length changes.
 */
export function speedChannels(
  channels: readonly Float32Array[],
  sampleRate: number,
  speed: number
): Float32Array[] {
  if (!(speed > 0) || speed === 1) {
    return [...channels];
  }
  return resampleChannels(channels, sampleRate * speed, sampleRate);
}
